import{_ as n,C as c,o as l,c as s,j as d,a as t,E as o,a5 as a}from"./chunks/framework.CINlqUGR.js";const v=JSON.parse('{"title":"JSON 视图","description":"","frontmatter":{},"headers":[],"relativePath":"components/json-viewer.md","filePath":"components/json-viewer.md","lastUpdated":1787599504000}'),h={name:"components/json-viewer.md"},p={id:"json-视图",tabindex:"-1"};function u(b,e,x,g,m,w){const i=c("Badge"),r=c("XhDemo");return l(),s("div",null,[d("h1",p,[e[0]||(e[0]=t("JSON 视图 ",-1)),o(i,{type:"info",text:"json-viewer"}),e[1]||(e[1]=t()),e[2]||(e[2]=d("a",{class:"header-anchor",href:"#json-视图","aria-label":'Permalink to "JSON 视图 <Badge type="info" text="json-viewer" />"'},"​",-1))]),e[3]||(e[3]=a('<p>把一份 JSON 摊成可展开的树：键名、值与值类型各自成一块，对象与数组可以逐层收起。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>调试面板、接口返回体、配置文件的只读呈现。</li><li>日志详情里那一大坨结构化字段，直接铺开会淹掉正文。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>数据是可编辑的：本组件只读，改值要自己接<a href="./form">表单</a>与<a href="./text-field">输入框</a>。</li><li>数据只是一段带语法高亮的源码：用<a href="./code-block">代码块</a>。</li><li>层级数据不是 JSON，键名与类型没有语义：用<a href="./tree">树</a>——它认的是通用层级数据与选中，本组件认的是 JSON 的类型语义（键名、值形态、逐类型着色、循环引用）。</li><li>只有几个字段要平铺展示：用<a href="./descriptions">描述列表</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>行结构由 <code>value</code> 摊出来，作者不写任何行标记：Vue 与自定义元素两侧铺出同一棵 DOM，根容器里原有的内容由组件接管。</li><li>不给 <code>value</code> 就是空视图，一行也不摊；对象内部真有一个值为 <code>undefined</code> 的成员时，那一行照常摊出来。</li><li>展开集合可受控（<code>expandedValue</code> / <code>defaultExpandedValue</code>），不受控时按 <code>defaultExpandedDepth</code> 现算：数据晚于组件挂载才到（自定义元素常是先升级、再由脚本写 <code>.value</code>）也照样算得上，第一次展开或收起之后就固定下来，不再跟着数据走。</li><li><code>maxStringLength</code> 截长字符串，<code>maxItems</code> 折超长数组，<code>sortKeys</code> 让对象键按字典序排。</li><li>循环引用摊到就停，标成 <code>[Circular]</code>，不会无限递归。</li><li>每一行带 <code>data-type</code>，六种值形态各自上色。</li><li>尺寸一轴与其余组件同源。</li><li><strong>只认 JSON 能表达的形状</strong>，喂进活对象时呈现是有损的：<code>Date</code> / <code>Map</code> / <code>Set</code> 一律按自有可枚举键摊，因此显示成 <code>{}</code>；<code>undefined</code> 归 <code>null</code> 一档、显示成 <code>undefined</code>；<code>bigint</code> 归 <code>number</code>；函数与 symbol 归 <code>string</code>，按各自的字符串形式呈现。要如实展示这些值，先自己转成 JSON 能表达的形状。</li><li>自定义元素侧：<code>value</code> 属性收的是一段 JSON 文本（解析不了就当一个字符串值展示），对象与数组直接赋 property（<code>el.value = { … }</code>）；<code>expandedValue</code> / <code>defaultExpandedValue</code> / <code>translations</code> <strong>没有对应属性，只能走 property</strong>，写成 <code>expanded-value=&#39;[&quot;$&quot;]&#39;</code> 不会生效。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>一份 JSON 摊成可展开的树：键名与值各自成块，六种类型各自上色，默认只展开根行</p>',10)),o(r,{src:"json-viewer/01-basic"}),e[4]||(e[4]=d("h3",{id:"默认展开层数",tabindex:"-1"},[t("默认展开层数 "),d("a",{class:"header-anchor",href:"#默认展开层数","aria-label":'Permalink to "默认展开层数"'},"​")],-1)),e[5]||(e[5]=d("p",null,"defaultExpandedDepth 决定初次摊到第几层：1 只展开根行，3 连孙层一起铺开",-1)),o(r,{src:"json-viewer/02-depth"}),e[6]||(e[6]=d("h3",{id:"受控展开",tabindex:"-1"},[t("受控展开 "),d("a",{class:"header-anchor",href:"#受控展开","aria-label":'Permalink to "受控展开"'},"​")],-1)),e[7]||(e[7]=d("p",null,"传了 expandedValue 就由宿主说了算，组件只发 expanded-change 不落内部值，写回它才动",-1)),o(r,{src:"json-viewer/03-controlled"}),e[8]||(e[8]=d("h3",{id:"大数据",tabindex:"-1"},[t("大数据 "),d("a",{class:"header-anchor",href:"#大数据","aria-label":'Permalink to "大数据"'},"​")],-1)),e[9]||(e[9]=d("p",null,"maxItems 把超长数组折成一行占位，maxStringLength 截掉过长的字符串，一份大 JSON 不会把页面压住",-1)),o(r,{src:"json-viewer/04-large"}),e[10]||(e[10]=d("h3",{id:"键排序",tabindex:"-1"},[t("键排序 "),d("a",{class:"header-anchor",href:"#键排序","aria-label":'Permalink to "键排序"'},"​")],-1)),e[11]||(e[11]=d("p",null,"sortKeys 让对象键按字典序排，数组顺序不动；接口返回的字段顺序不稳定时用它",-1)),o(r,{src:"json-viewer/05-sort-keys"}),e[12]||(e[12]=d("h3",{id:"循环引用",tabindex:"-1"},[t("循环引用 "),d("a",{class:"header-anchor",href:"#循环引用","aria-label":'Permalink to "循环引用"'},"​")],-1)),e[13]||(e[13]=d("p",null,"值出现在自己的祖先链上就停下并标成 [Circular]，不会无限递归；共享引用不算环，照样摊开",-1)),o(r,{src:"json-viewer/06-circular"}),e[14]||(e[14]=d("h3",{id:"尺寸",tabindex:"-1"},[t("尺寸 "),d("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),e[15]||(e[15]=d("p",null,"size 三档只换字号与层级缩进，行的结构与配色都不变",-1)),o(r,{src:"json-viewer/07-size"}),e[16]||(e[16]=d("h3",{id:"原文视图",tabindex:"-1"},[t("原文视图 "),d("a",{class:"header-anchor",href:"#原文视图","aria-label":'Permalink to "原文视图"'},"​")],-1)),e[17]||(e[17]=d("p",null,'view="text" 直接出缩进过的 JSON 原文：整块可框选可复制，且不受 maxStringLength / maxItems 折减',-1)),o(r,{src:"json-viewer/08-text"}),e[18]||(e[18]=a('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-json-viewer&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhJsonViewerRoot</code></td></tr><tr><td>组合式函数</td><td><code>useJsonViewer</code></td></tr><tr><td>状态机</td><td><code>jsonViewerMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/json-viewer.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;json-viewer&quot;</code>：<strong><code>root</code></strong> · <code>tree</code> · <code>item</code> · <code>item-key</code> · <code>item-value</code> · <code>branch</code> · <code>branch-control</code> · <code>branch-trigger</code> · <code>branch-indicator</code> · <code>branch-text</code> · <code>branch-content</code> · <code>preview</code> · <code>text</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>unknown</code></td><td></td><td>要展示的值，任意形状。缺省即空视图（一行也不摊）。</td></tr><tr><td><code>view</code></td><td><code>JsonViewerView</code></td><td></td><td>展示形态，默认 tree。 text 档直接出 JSON 原文：整块可框选可复制，且不受 maxStringLength / maxItems 折减—— 要的就是与后端下发的那份一字不差。展开集合与键盘导航在这一档上不起作用。</td></tr><tr><td><code>expandedValue</code></td><td><code>string[]</code></td><td></td><td>展开集合（元素是行路径）。给定即受控：cell 直读 prop，写只发 onExpandedChange 不落内部值。</td></tr><tr><td><code>defaultExpandedValue</code></td><td><code>string[]</code></td><td></td><td>非受控初值；不给就按 defaultExpandedDepth 现算。</td></tr><tr><td><code>defaultExpandedDepth</code></td><td><code>number</code></td><td></td><td>初始展开到第几层（层级号不超过它的分支全部展开），默认 1，即只展开根行。</td></tr><tr><td><code>maxStringLength</code></td><td><code>number</code></td><td></td><td>字符串值超过这么多字符就截断并补省略号；不给即不截断。</td></tr><tr><td><code>maxItems</code></td><td><code>number</code></td><td></td><td>同一层最多摊出这么多成员，其余收成一行占位；不给即全摊。</td></tr><tr><td><code>sortKeys</code></td><td><code>boolean</code></td><td></td><td>对象键按字典序排列；数组顺序不受影响。</td></tr><tr><td><code>loop</code></td><td><code>boolean</code></td><td></td><td>上下键走到首尾是否回绕，默认 false。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，只对调左右方向键的展开/收起语义；不给即从 DOM 现读。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;JsonViewerTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onExpandedChange</code></td><td><code>(details: JsonViewerExpandedChangeDetails) =&gt; void</code></td><td></td><td></td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>expanded-change</code></td><td><code>JsonViewerExpandedChangeDetails</code></td><td>展开集合变化；detail 为 <code>{ value: string[] }</code></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>EXPANDED.SET</code> · <code>BRANCH.EXPAND</code> · <code>BRANCH.COLLAPSE</code> · <code>BRANCH.TOGGLE</code> · <code>NODE.FOCUS</code> · <code>VIEWER.BLUR</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useJsonViewer</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>visibleNodes</code></td><td><code>readonly JsonViewerNode[]</code></td><td>当前可见行序列（收起分支的子行不在其中）。 方向键、Home/End 都在它上面走，适配器也按它铺 DOM。</td></tr><tr><td><code>expandedValue</code></td><td><code>string[]</code></td><td></td></tr><tr><td><code>focusedValue</code></td><td><code>string | null</code></td><td>roving tabindex 的锚点行：焦点在树内时就是当前行，焦点离开后仍留着（Tab 回来落回它）； 它已随分支收起而不再可见时为 null。</td></tr><tr><td><code>isFocusWithin</code></td><td><code>boolean</code></td><td>焦点此刻在不在树内。行的高亮标记跟它走，锚点不跟。</td></tr><tr><td><code>isExpanded</code></td><td><code>(value: string) =&gt; boolean</code></td><td></td></tr><tr><td><code>previewText</code></td><td><code>(node: JsonViewerNode) =&gt; string</code></td><td>分支收起摘要的显示文字（如 <code>{…} 3</code>），只给眼睛看；叶子行返回空串。</td></tr><tr><td><code>valueText</code></td><td><code>(node: JsonViewerNode) =&gt; string</code></td><td>值的显示文字；截断占位行返回「其余 N 项」那句话。</td></tr><tr><td><code>setExpandedValue</code></td><td><code>(next: string[]) =&gt; void</code></td><td></td></tr><tr><td><code>expand</code></td><td><code>(value: string) =&gt; void</code></td><td></td></tr><tr><td><code>collapse</code></td><td><code>(value: string) =&gt; void</code></td><td></td></tr><tr><td><code>toggle</code></td><td><code>(value: string) =&gt; void</code></td><td></td></tr><tr><td><code>view</code></td><td><code>JsonViewerView</code></td><td>当前生效的展示形态。</td></tr><tr><td><code>text</code></td><td><code>string</code></td><td>缩进过的 JSON 原文；键序与环路记号与树档一致。text 档之外也取得到，方便作者做「复制原文」。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTreeProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTextProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: JsonViewerNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemKeyProps</code></td><td><code>(props: JsonViewerNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemValueProps</code></td><td><code>(props: JsonViewerNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBranchProps</code></td><td><code>(props: JsonViewerNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBranchControlProps</code></td><td><code>(props: JsonViewerNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBranchTriggerProps</code></td><td><code>(props: JsonViewerNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBranchIndicatorProps</code></td><td><code>(props: JsonViewerNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBranchTextProps</code></td><td><code>(props: JsonViewerNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBranchContentProps</code></td><td><code>(props: JsonViewerNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPreviewProps</code></td><td><code>(props: JsonViewerNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/treeview/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>focus outside the tree</td><td>整棵树只占一个 Tab 位：第一次进来落首行，之后回到上次停留的那一行</td></tr><tr><td><code>ArrowDown</code></td><td>focus in tree</td><td>焦点移到下一个可见行（loop 默认关，末行不回绕）</td></tr><tr><td><code>ArrowUp</code></td><td>focus in tree</td><td>焦点移到上一个可见行（loop 默认关，首行不回绕）</td></tr><tr><td><code>Home</code></td><td>focus in tree</td><td>焦点移到首个可见行</td></tr><tr><td><code>End</code></td><td>focus in tree</td><td>焦点移到末个可见行（展开着的子层也算行）</td></tr><tr><td><code>ArrowRight</code></td><td>focus on branch（dir=rtl 时改由 ArrowLeft 承担）</td><td>收起的对象/数组就地展开；已展开则把焦点移到首个子行；标量行什么都不做且不吞键</td></tr><tr><td><code>ArrowLeft</code></td><td>focus in tree（dir=rtl 时改由 ArrowRight 承担）</td><td>展开的对象/数组就地收起；收起的分支与标量行则把焦点移到父行；根行什么都不做</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus on branch</td><td>切换该分支的展开态；焦点在标量行上时不吞这两个键</td></tr><tr><td><code>*</code></td><td>focus in tree</td><td>展开与焦点行同一父级的全部分支（已展开的不动）；同级没有可展开的分支时不吞这个键</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>tree</code></td><td><code>aria-label</code></td><td>label.tree</td></tr><tr><td><code>tree</code></td><td><code>role</code></td><td>&#39;tree&#39;</td></tr><tr><td><code>branch</code></td><td><code>aria-expanded</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>branch</code></td><td><code>aria-label</code></td><td>branchLabel(node) | undefined</td></tr><tr><td><code>branch-trigger</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>branch-indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>branch-content</code></td><td><code>role</code></td><td>&#39;group&#39;</td></tr><tr><td><code>preview</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>text</code></td><td><code>aria-label</code></td><td>label.text</td></tr><tr><td><code>text</code></td><td><code>role</code></td><td>&#39;region&#39;</td></tr></tbody></table><ul><li>树是 <code>role=tree</code>，每一行是 <code>role=treeitem</code>，层级三件套（<code>aria-level</code> / <code>aria-posinset</code> / <code>aria-setsize</code>）取自摊平结果。</li><li>整棵树只占一个 Tab 位：第一次进来落在首行，之后 Tab 出去再回来落回上次停留的那一行；组内靠上下键走。</li><li>展开箭头对读屏隐藏——它重复的是分支自己已经报出的 <code>aria-expanded</code> 与左右方向键。</li><li>分支的名字显式给（<code>aria-label</code>）：它裹着整棵子层，从内容算名字会把所有子孙的文字一并念出来。</li><li>收起摘要（<code>{…} 3</code>）是排版记号，对读屏隐藏；里面那个成员数折进了分支的可及名字（默认念成 <code>tags, 3 items</code>，整句可用 <code>translations.collapsedBranchLabel</code> 换）。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/json-viewer.css</code> 按部件选择：<code>[data-scope=&quot;json-viewer&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-view</code></td><td>props.view</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-json-viewer-bg</code> · <code>--xh-json-viewer-boolean-fg</code> · <code>--xh-json-viewer-border</code> · <code>--xh-json-viewer-fg</code> · <code>--xh-json-viewer-font</code> · <code>--xh-json-viewer-font-size</code> · <code>--xh-json-viewer-icon-size</code> · <code>--xh-json-viewer-indent</code> · <code>--xh-json-viewer-indicator-fg</code> · <code>--xh-json-viewer-indicator-size</code> · <code>--xh-json-viewer-key-fg</code> · <code>--xh-json-viewer-key-font-weight</code> · <code>--xh-json-viewer-max-h</code> · <code>--xh-json-viewer-null-fg</code> · <code>--xh-json-viewer-number-fg</code> · <code>--xh-json-viewer-preview-fg</code> · <code>--xh-json-viewer-preview-font-size</code> · <code>--xh-json-viewer-punctuation-fg</code> · <code>--xh-json-viewer-px</code> · <code>--xh-json-viewer-py</code> · <code>--xh-json-viewer-radius</code> · <code>--xh-json-viewer-row-bg-hover</code> · <code>--xh-json-viewer-row-gap</code> · <code>--xh-json-viewer-row-px</code> · <code>--xh-json-viewer-row-py</code> · <code>--xh-json-viewer-row-radius</code> · <code>--xh-json-viewer-string-fg</code> · <code>--xh-json-viewer-text-fg</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像；另有按 <code>dir</code> 分支的规则。</p><ul><li>左右方向键的展开/收起语义跟着书写方向走：没传 <code>dir</code> 时从 DOM 现读，整页 <code>dir=&quot;rtl&quot;</code> 也认得出来。</li></ul><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>放进<a href="./tabs">标签页</a>或<a href="./drawer">抽屉</a>里当调试面板；行数多时套一层<a href="./scroll-area">滚动区域</a>。</li><li>配<a href="./clipboard">复制到剪贴板</a>让人把原始 JSON 拿走。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>大数据一定要给 <code>maxItems</code> 与 <code>maxStringLength</code>：一次摊开几万行会让页面停住。</li><li>默认展开层数别给大：<code>defaultExpandedDepth</code> 超过 2 就等于把整份数据铺满屏。</li><li>值里的类型只靠颜色区分是不够的，字符串的引号、<code>null</code> 的字面量都要留着。</li><li>一行被收起时，它内部那个持有焦点的行会随之离开 DOM，焦点掉回 <code>&lt;body&gt;</code>。要在收起前把焦点交回分支行本身，键盘用户才不会每收一层就丢一次位置。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>拿它当日志流：日志是时间序的一串条目，用<a href="./log">日志</a>。</li><li>把一份几 MB 的响应体原样丢进去，再让用户自己找。</li></ul>',44))])}const P=n(h,[["render",u]]);export{v as __pageData,P as default};
